TYPES_EN = {"Saisi": "Input", "Calculé": "Calculated", "Facteur d'émission": "Emission factor"}


def creer_langues(apps, schema_editor):
    """Français et anglais actifs ; la langue de référence est la langue par défaut actuelle (fr pour une base créée avant les langues)."""
    Instance, Langue = apps.get_model("parametres", "Instance"), apps.get_model("parametres", "Langue")
    i = Instance.objects.filter(pk=1).first()
    ref = (i.langue if i else "") or "fr"
    if i:
        i.langue_reference = ref
        i.save(update_fields=["langue_reference"])
    for ordre, (code, libelle) in enumerate(LANGUES, start=1):
        Langue.objects.get_or_create(code=code, defaults={"libelle": libelle, "ordre": ordre, "active": True})
    if not Langue.objects.filter(code=ref).exists():
        Langue.objects.create(code=ref, libelle=ref, ordre=0, active=True)
    if ref != "fr":
        return
    # libellés anglais de l'ancien export « English labels » : l'export en anglais reste le même
    for modele, champs, textes in (("NiveauHierarchique", ("nom", "nom_pluriel"), NIVEAUX_EN), ("TypeSaisie", ("libelle",), TYPES_EN)):
        for o in apps.get_model("parametres", modele).objects.all():
            en = {c: textes[getattr(o, c)] for c in champs if getattr(o, c) in textes}
            if en and not (o.traductions or {}).get("en"):
                o.traductions = {**(o.traductions or {}), "en": en}
                o.save(update_fields=["traductions"])


